    from collections import deque

    rows = len(grid)
    if rows == 0: return grid
    cols = len(grid[0])

    # Count color frequencies
    color_counts = {}
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            color_counts[color] = color_counts.get(color, 0) + 1

    # Identify colors
    background = 0
    non_background = {k: v for k, v in color_counts.items() if k != background}

    # Most frequent non-background is wall
    # Least frequent non-background is seed
