        wall_color = max(non_background, key=lambda x: non_background[x])
        seed_color = min(non_background, key=lambda x: non_background[x])
    else:
        # Fallback: seed is the non-background color
        seed_color = list(non_background.keys())[0]

    # Flood fill from all seed pixels
    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == seed_color:
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
